/* Satu node memegang setiap aturan yang menentukan apakah uang keluar.
   Urutannya disengaja dan penting:

     1. rekening vendor tidak ada   - tidak bisa membayar ke ketiadaan
     2. vendor ditahan (sanksi)     - halangan hukum, diperiksa sebelum urusan uang
     3. sudah dibayar               - DUPLICATE: transfer tidak bisa ditarik kembali
        atau sedang dibayar         - IN_FLIGHT: sudah di berkas bank yang belum dibalas
     4. rekening baru berubah       - penipuan pengalihan pembayaran
     5. belum disetujui             - atau disetujui orang yang kewenangannya kurang
     6. nilai terlalu kecil         - biaya transfer melebihi manfaatnya
     7. kas tidak cukup             - ini penjadwalan, bukan penolakan, jadi paling akhir

   Nomor 4 diperiksa SEBELUM persetujuan, dengan sengaja: faktur yang masih
   menunggu tanda tangan tetap ditandai bila rekening vendornya baru berubah,
   supaya penyetuju tahu sebelum menandatangani - bukan sesudahnya.

   Nomor 3 menghitung dua keadaan. Versi sebelumnya hanya menghitung yang sudah
   LUNAS, sehingga menjalankan run dua kali sebelum bank membalas mengajukan
   faktur yang sama di berkas kedua - pembayaran ganda dari satu klik.

   Nomor 5 juga baru. Versi sebelumnya membayar faktur needs_approval seolah
   sudah disetujui: pencocokan tiga arah yang bersih dianggap persetujuan,
   padahal pencocokan hanya membuktikan fakturnya benar, bukan bahwa orang yang
   berwenang sudah setuju membayarnya. */

const HARI_REKENING_BARU   = 14;
const PLAFON_TANPA_SENTUH  = 10000000;
const PLAFON_MANAJER       = 100000000;
const PLAFON_DIREKTUR      = 400000000;
const MIN_BAYAR            = 100000;

/* Tingkat kewenangan penyetuju. Faktur yang dirutekan ke direktur tidak sah
   disetujui manajer, meskipun kolom penyetujunya terisi. */
const TINGKAT = { manager: 1, director: 2 };

function toNum(v){ if(v===null||v===undefined||v==='') return 0;
  const n = Number(String(v).split(',').join('')); return isNaN(n)?0:n; }
function hariAntara(a,b){ const x=Date.parse(a), y=Date.parse(b);
  if(isNaN(x)||isNaN(y)) return null; return Math.round((y-x)/86400000); }
function samar(no){ const s=String(no||''); return s.length<5 ? '****' : '******'+s.slice(-4); }
function rp(n){ return Number(n||0).toLocaleString('id-ID'); }

const hariIni = new Date().toISOString().slice(0,10);
const runIni = 'RUN-' + String($execution.id||'manual');

/* --- master --- */
const bankVendor = {};
for (const it of $('Muat Rekening Vendor').all()) {
  const r = it.json || {};
  if (r.vendor) bankVendor[String(r.vendor).trim().toUpperCase()] = r;
}

/* Pembayaran terdahulu, dari baris yang benar-benar ada di tabel.
   settled            = sudah lunas.
   to_pay dari run LAIN = sudah masuk berkas bank, balasan banknya belum datang.
   rejected sengaja tidak dihitung: transfer yang ditolak berarti vendor belum
   dibayar, dan fakturnya memang harus bisa diajukan lagi. */
const akunArr = $('Muat Posisi Kas').all().map(function(i){ return i.json; })
  .filter(function(a){ return a && a.account_code; });
const akun = akunArr[0] || { account_code:'(tidak ada)', balance:0, min_buffer:0, cost_of_cash_pct:0, currency:'IDR' };
const saldo = toNum(akun.balance);
const buffer = toNum(akun.min_buffer);
const saldoPer = String(akun.as_of||'').slice(0,10);

const sudahDibayar = {};
const sedangDibayar = {};
let dalamPerjalanan = 0;     /* di berkas bank, belum dibalas */
let lunasSetelahSaldo = 0;   /* lunas pada atau sesudah tanggal saldo dicatat */
for (const it of $('Muat Pembayaran Sebelumnya').all()) {
  const r = it.json || {};
  if (!r.vendor || !r.invoice_number) continue;
  const kunci = String(r.vendor).trim().toUpperCase() + '|' + String(r.invoice_number).trim();
  const st = String(r.status||'');
  const bersih = toNum(r.amount) - toNum(r.discount_taken);
  if (st === 'settled') {
    sudahDibayar[kunci] = r;
    if (saldoPer && String(r.settled_on||'').slice(0,10) >= saldoPer) lunasSetelahSaldo += bersih;
  } else if (st === 'to_pay' && String(r.run_key||'') !== runIni) {
    sedangDibayar[kunci] = r;
    dalamPerjalanan += bersih;
  }
}

/* Saldo di PAY Bank Accounts adalah potret pada tanggal as_of. Uang yang sudah
   ada di berkas bank tapi belum dibalas, dan pembayaran yang lunas sejak potret
   itu, belum tercermin di sana - keduanya dikurangkan. Tanpa itu, run kedua
   menganggap uang run pertama masih bebas dan menjanjikannya dua kali.
   Pembayaran yang lunas pada HARI YANG SAMA dengan potret ikut dikurangkan:
   bisa jadi terhitung dua kali, tapi kesalahan ke arah itu hanya menunda
   pembayaran, sedangkan kesalahan ke arah sebaliknya membuat rekening minus. */
const bolehPakai = Math.max(0, saldo - buffer - dalamPerjalanan - lunasSetelahSaldo);
const biayaKasPct = toNum(akun.cost_of_cash_pct);

/* --- faktur dari buku besar AP --- */
/* auto_approve dan needs_approval sama-sama lolos pencocokan tiga arah. Yang
   needs_approval ikut dimuat bukan karena boleh dibayar, tapi supaya yang masih
   menunggu tanda tangan TERCATAT beserta alasannya (kontrol nomor 5), bukan
   hilang diam-diam dari run. */
const faktur = [];
for (const it of $('Muat Faktur Disetujui').all()) {
  const r = it.json || {};
  const d = String(r.decision||'');
  if (d !== 'auto_approve' && d !== 'needs_approval') continue;
  const jml = toNum(r.amount);
  if (jml <= 0) continue;
  faktur.push(r);
}

function persetujuan(f){
  if (String(f.decision) === 'auto_approve')
    return { sah:true, oleh:'pencocokan tiga arah, di bawah plafon tanpa sentuhan' };
  const perlu = String(f.route_to||'manager');
  const oleh = String(f.approved_by||'').trim();
  const peran = String(f.approved_role||'').trim();
  if (!oleh)
    return { sah:false, alasan:'Belum disetujui. Pencocokan tiga arahnya bersih, tapi faktur ini masih menunggu persetujuan ' + perlu + '.' };
  if ((TINGKAT[peran]||0) < (TINGKAT[perlu]||1))
    return { sah:false, alasan:'Disetujui ' + oleh + ' sebagai ' + (peran||'peran tidak tercatat') + ', padahal faktur ini butuh persetujuan ' + perlu + '. Persetujuan dari kewenangan yang kurang tidak dihitung.' };
  return { sah:true, oleh: oleh + ' (' + peran + (f.approved_on ? ', ' + String(f.approved_on).slice(0,10) : '') + ')' };
}

/* Diskon bayar-awal hanya diambil kalau memang menguntungkan. "2/10 NET 30"
   berarti hemat 2% bila dibayar 20 hari lebih cepat; itu setara bunga tahunan
   sekitar 36%, jauh di atas biaya kas 12%, jadi layak diambil. Membandingkan
   keduanya - bukan sekadar melihat ada diskon - adalah bedanya bendahara yang
   berhitung dengan yang sekadar cepat membayar. */
function bacaTermin(teks){
  const t = String(teks||'NET 30').toUpperCase();
  const net = (t.match(/NET\s*(\d+)/)||[])[1];
  const disk = t.match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+)/);
  return { netHari: net?parseInt(net,10):30,
           diskonPct: disk?parseFloat(disk[1]):0,
           diskonHari: disk?parseInt(disk[2],10):0 };
}

const keluar = [];
let dipakai = 0;
const sudahDinilai = {};

/* Urutan pembayaran: yang menghasilkan diskon dulu (itu uang nyata yang hilang
   kalau lewat tanggal), lalu yang paling tua. */
faktur.sort(function(a,b){
  const ta = bacaTermin((bankVendor[String(a.vendor||'').trim().toUpperCase()]||{}).payment_terms);
  const tb = bacaTermin((bankVendor[String(b.vendor||'').trim().toUpperCase()]||{}).payment_terms);
  if ((tb.diskonPct>0) !== (ta.diskonPct>0)) return tb.diskonPct>0 ? 1 : -1;
  return String(a.processed_at||'').localeCompare(String(b.processed_at||''));
});

for (const f of faktur) {
  const vendor = String(f.vendor||'').trim();
  const vKey = vendor.toUpperCase();
  const noFaktur = String(f.invoice_number||'').trim();
  const kunci = vKey + '|' + noFaktur;
  const jml = toNum(f.amount);
  const bank = bankVendor[vKey] || null;
  const termin = bacaTermin(bank ? bank.payment_terms : 'NET 30');
  const setuju = persetujuan(f);

  let status='', rute='', kodeTahan='', alasan='', diskon=0, bayarPada='';

  const umurFaktur = hariAntara(String(f.processed_at||'').slice(0,10), hariIni);
  const dalamJendelaDiskon = termin.diskonPct>0 && umurFaktur!==null && umurFaktur <= termin.diskonHari;
  const hematJika = Math.round(jml * termin.diskonPct / 100);
  const hariDipercepat = Math.max(0, termin.netHari - (umurFaktur||0));
  const biayaKas = Math.round(jml * (biayaKasPct/100) * (hariDipercepat/365));
  const diskonLayak = dalamJendelaDiskon && hematJika > biayaKas;

  const hariSejakUbah = bank ? hariAntara(bank.changed_on, hariIni) : null;

  if (!bank) {
    status='held'; rute='ap_clerk'; kodeTahan='NO_BANK_DETAILS';
    alasan='Tidak ada rekening terverifikasi untuk ' + vendor + '. Tidak ada tujuan transfer.';
  } else if (bank.sanctions_flag === true) {
    status='held'; rute='legal'; kodeTahan='SANCTIONS';
    alasan=vendor + ' sedang ditahan: ' + (bank.notes || 'ditandai pada daftar tahan') + ' Legal harus melepas dulu.';
  } else if (sudahDibayar[kunci]) {
    const lama = sudahDibayar[kunci];
    status='held'; rute='ap_supervisor'; kodeTahan='DUPLICATE';
    alasan='Faktur ini sudah dibayar pada ' + String(lama.settled_on || lama.pay_on || 'run sebelumnya')
      + ' (ref ' + String(lama.bank_ref||'-') + '). Membayarnya lagi tidak bisa ditarik kembali.';
  } else if (sedangDibayar[kunci] || sudahDinilai[kunci]) {
    const lama = sedangDibayar[kunci];
    status='held'; rute='treasury'; kodeTahan='IN_FLIGHT';
    alasan = lama
      ? 'Faktur ini sudah ada di berkas bank ' + String(lama.run_key||'-') + ' (' + String(lama.pay_on||'-')
        + ') dan balasan banknya belum masuk. Mengajukannya lagi sekarang berarti membayar dua kali bila berkas pertama lunas. '
        + 'Kalau bank menolaknya, faktur ini diajukan lagi dengan sendirinya di run berikutnya.'
      : 'Faktur yang sama muncul lebih dari sekali di buku besar AP pada run ini. Hanya yang pertama dinilai.';
  } else if (hariSejakUbah !== null && hariSejakUbah <= HARI_REKENING_BARU) {
    status='held'; rute='treasury'; kodeTahan='BANK_CHANGED';
    alasan='Nomor rekening ' + vendor + ' berubah ' + hariSejakUbah + ' hari lalu lewat '
      + String(bank.change_channel||'jalur tidak tercatat') + ' oleh ' + String(bank.changed_by||'tidak diketahui')
      + '. Telepon vendor memakai nomor LAMA yang tersimpan, bukan kontak apa pun di pesan yang meminta perubahan.';
  } else if (!setuju.sah) {
    status='held'; rute=String(f.route_to||'manager'); kodeTahan='AWAITING_APPROVAL';
    alasan=setuju.alasan;
  } else if (jml < MIN_BAYAR) {
    status='held'; rute='ap_clerk'; kodeTahan='TOO_SMALL';
    alasan='Nilainya ' + rp(jml) + ', di bawah ambang ' + rp(MIN_BAYAR) + ' - biaya transfer melebihi manfaatnya. '
      + 'Tidak ada yang menggabungkannya otomatis: AP clerk yang memutuskan kapan dibayar.';
  } else if (dipakai + jml > bolehPakai) {
    status='held'; rute='treasury'; kodeTahan='CASH_SHORT';
    alasan='Kas yang boleh dipakai ' + rp(bolehPakai) + ' (saldo ' + rp(saldo) + ' dikurangi cadangan ' + rp(buffer)
      + (dalamPerjalanan ? ', dikurangi ' + rp(dalamPerjalanan) + ' yang sudah di berkas bank tapi belum dibalas' : '')
      + (lunasSetelahSaldo ? ', dikurangi ' + rp(lunasSetelahSaldo) + ' yang lunas sejak saldo dicatat' : '')
      + '). Run ini sudah mengalokasikan ' + rp(dipakai) + ', sedangkan tagihan ini ' + rp(jml) + '. Ditunda, bukan ditolak.';
  } else {
    status='to_pay';
    diskon = diskonLayak ? hematJika : 0;
    bayarPada = hariIni;
    dipakai = dipakai + (jml - diskon);
    if (jml <= PLAFON_TANPA_SENTUH) rute='accounting_auto';
    else if (jml <= PLAFON_MANAJER) rute='manager';
    else if (jml <= PLAFON_DIREKTUR) rute='director';
    else rute='dual_signature';
  }
  sudahDinilai[kunci] = true;

  keluar.push({ json: {
    line_key: runIni + '|' + vKey + '|' + noFaktur,
    run_key: runIni,
    vendor: vendor, invoice_number: noFaktur,
    amount: jml, currency: String(f.currency||'IDR'),
    status: status, route_to: rute, hold_code: kodeTahan, hold_reason: alasan,
    account_number_masked: bank ? samar(bank.account_number) : '',
    bank_name: bank ? String(bank.bank_name||'') : '',
    account_name: bank ? String(bank.account_name||'') : '',
    pay_on: bayarPada, discount_taken: diskon,
    bank_ref: '', settled_on: '', reject_reason: '',
    net_amount: jml - diskon,
    payment_terms: termin.diskonPct>0 ? (termin.diskonPct + '/' + termin.diskonHari + ' NET ' + termin.netHari) : ('NET ' + termin.netHari),
    diskon_tersedia: hematJika, diskon_layak: diskonLayak, biaya_kas: biayaKas,
    umur_faktur_hari: umurFaktur,
    disetujui_oleh: setuju.sah ? setuju.oleh : '',
    butuh_tanda_tangan_ganda: rute === 'dual_signature',
    akun_sumber: akun.account_code,
    kas_boleh_dipakai: bolehPakai, kas_terpakai_sampai_baris_ini: dipakai,
    execution_id: String($execution.id||'manual')
  }});
}
return keluar;

