/* Berkas instruksi bank. Yang membuatnya berarti bukan formatnya, tapi total
   kendali dan checksum-nya: bank menolak berkas yang jumlahnya tidak cocok,
   dan itulah yang menghentikan satu baris terselip atau berubah di tengah jalan.
   Berkas tanpa total kendali hanya terlihat seperti berkas.

   Hanya baris yang BENAR-BENAR tersimpan di tabel yang masuk berkas. Versi
   sebelumnya membangun berkas dari keputusan mesin: baris yang gagal tersimpan
   tetap dibayar, lalu tidak terlihat oleh penjaga pembayaran ganda di run
   berikutnya - dan dibayar lagi. */
const tersimpan = {};
try {
  for (const it of $('Tulis Baris Pembayaran').all()) {
    const r = it.json || {};
    if (r.id !== undefined && r.id !== null && r.line_key) tersimpan[r.line_key] = true;
  }
} catch (e) {}

const semua = $('Kumpulkan Semua Baris').all().map(function(i){ return i.json; });
const diputuskan = semua.filter(function(r){ return r.status === 'to_pay'; });
const bayar = diputuskan.filter(function(r){ return tersimpan[r.line_key]; });

function rp(n){ return Number(n||0).toLocaleString('id-ID'); }

const baris = bayar.map(function(r, i){
  return [ String(i+1).padStart(4,'0'), r.vendor, r.account_number_masked,
           r.bank_name, String(r.net_amount), r.currency, r.invoice_number ].join(',');
});
const total = bayar.reduce(function(s,r){ return s + Number(r.net_amount||0); }, 0);

/* Checksum sederhana yang dapat dihitung ulang siapa pun dari isi berkas.
   Bukan kriptografi - tugasnya cuma membuktikan berkas tidak berubah sejak dibuat. */
let sum = 0;
const isi = baris.join('\n');
for (let i = 0; i < isi.length; i++) { sum = (sum * 31 + isi.charCodeAt(i)) % 2147483647; }

const kepala = 'HDR,' + String($execution.id||'manual') + ',' + new Date().toISOString().slice(0,10)
  + ',' + bayar.length + ',' + total;
const kaki = 'TRL,' + bayar.length + ',' + total + ',' + sum;

return [{ json: {
  run_key: 'RUN-' + String($execution.id||'manual'),
  jumlah_baris: bayar.length,
  control_total: total,
  file_checksum: String(sum),
  bayar_tidak_tersimpan: diputuskan.length - bayar.length,
  nama_berkas: 'PAYRUN-' + String($execution.id||'manual') + '.csv',
  isi_berkas: [kepala].concat(baris).concat([kaki]).join('\n'),
  ringkas_teks: bayar.length + ' baris, total ' + rp(total) + ' IDR, checksum ' + sum
}}];

/* Dua jenis angka, sengaja dibedakan:
   - dibayar, tertahan, dan diskon dihitung dari keputusan mesin, sebelum ditulis;
   - "Baris tersimpan" dihitung dari baris yang BENAR-BENAR dikembalikan tabel,
     dan berkas bank hanya memuat baris yang tersimpan (lihat Bangun Berkas Bank).
   Kalau keduanya berbeda, laporan menyebutnya: itu tanda ada pembayaran yang
   diputuskan tapi tidak tercatat, dan karena itu tidak ikut dikirim. */
function rp(n){ return Number(n||0).toLocaleString('id-ID'); }

let tertulis = [];
try { tertulis = $('Tulis Baris Pembayaran').all().map(function(i){ return i.json; })
       .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { tertulis = []; }

const diminta = $('Kumpulkan Semua Baris').all().map(function(i){ return i.json; });
const berkas = $('Bangun Berkas Bank').first().json;

const bayar  = diminta.filter(function(r){ return r.status==='to_pay'; });
const tahan  = diminta.filter(function(r){ return r.status==='held'; });
const ganda  = tahan.filter(function(r){ return r.hold_code==='DUPLICATE'; });
const tipu   = tahan.filter(function(r){ return r.hold_code==='BANK_CHANGED'; });
const sanksi = tahan.filter(function(r){ return r.hold_code==='SANCTIONS'; });
const kas    = tahan.filter(function(r){ return r.hold_code==='CASH_SHORT'; });
const ttd2   = bayar.filter(function(r){ return r.butuh_tanda_tangan_ganda; });

function jum(a,f){ return a.reduce(function(s,r){ return s + Number(r[f]||0); }, 0); }

const akunKode = (diminta[0]||{}).akun_sumber || '-';
const bolehPakai = Number((diminta[0]||{}).kas_boleh_dipakai || 0);
const nilaiBayar = jum(bayar,'net_amount');
const diskon = jum(bayar,'discount_taken');

const perKode = {};
for (const r of tahan) {
  const k = r.hold_code || 'LAIN';
  if (!perKode[k]) perKode[k] = { kode:k, jumlah:0, nilai:0, pemilik:{} };
  perKode[k].jumlah++; perKode[k].nilai += Number(r.amount||0);
  perKode[k].pemilik[r.route_to||'-'] = true;
}

return [{ json: {
  run_key: 'RUN-' + String($execution.id||'manual'),
  run_date: new Date().toISOString().slice(0,10),
  status: 'file_built',
  lines_total: diminta.length,
  lines_paid: bayar.length,
  lines_held: tahan.length,
  value_paid: nilaiBayar,
  value_held: jum(tahan,'amount'),
  control_total: Number(berkas.control_total||0),
  file_checksum: String(berkas.file_checksum||''),
  account_code: akunKode,
  balance_before: bolehPakai,
  balance_after: bolehPakai - nilaiBayar,
  settled_count: 0,
  rejected_count: 0,
  execution_id: String($execution.id||'manual'),

  baris_tertulis: tertulis.length,
  baris_tidak_tertulis: diminta.length - tertulis.length,
  diskon_diambil: diskon,
  butuh_ttd_ganda: ttd2.length,
  tahan_ganda: ganda.length, tahan_penipuan: tipu.length,
  tahan_sanksi: sanksi.length, tahan_kas: kas.length,
  rincian_tahan: Object.keys(perKode).map(function(k){
    return { kode:k, jumlah:perKode[k].jumlah, nilai:perKode[k].nilai,
             pemilik:Object.keys(perKode[k].pemilik).join(', ') };
  }).sort(function(a,b){ return b.nilai - a.nilai; }),
  daftar_tahan: tahan.map(function(r){
    return { vendor:r.vendor, faktur:r.invoice_number, nilai:r.amount,
             kode:r.hold_code, pemilik:r.route_to, alasan:r.hold_reason };
  }),
  daftar_bayar: bayar.map(function(r){
    return { vendor:r.vendor, faktur:r.invoice_number, bruto:r.amount,
             diskon:r.discount_taken, bersih:r.net_amount, rute:r.route_to,
             rekening:r.account_number_masked };
  })
}}];

