/* Bank membalas setelah berkas diproses. Sebagian baris lunas, sebagian
   ditolak - rekening tutup, nama tidak cocok, dana kurang. Balasan ini harus
   dibaca kembali, kalau tidak catatan kita mengklaim semuanya terbayar padahal
   tidak. Inilah bagian yang paling sering hilang dari otomasi pembayaran.

   Setiap balasan dicocokkan dengan baris yang BENAR-BENAR ada di berkas run itu.
   Versi sebelumnya menulis balasan apa pun lewat upsert: balasan untuk baris yang
   tidak pernah dikirim menciptakan baris pembayaran "lunas" yang tidak pernah ada,
   dan baris palsu itu dibaca penjaga pembayaran ganda sebagai bukti faktur sudah
   dibayar. Balasan seperti itu kini ditandai tidak_dikenal dan tidak ditulis. */
const webhook = $('Balasan Bank (Webhook)').first().json || {};
const badan = webhook.body || webhook;
const runKey = String(badan.run_key || '').trim();
const hasil = Array.isArray(badan.results) ? badan.results : [];
const hariIni = new Date().toISOString().slice(0,10);

const barisRun = $('Muat Baris Terkirim').all().map(function(i){ return i.json; })
  .filter(function(r){ return r && r.line_key && String(r.run_key||'') === runKey; });
const perKunci = {};
for (const r of barisRun) perKunci[r.line_key] = r;
/* Baris yang masuk berkas: semua kecuali yang ditahan. */
const diBerkas = barisRun.filter(function(r){ return String(r.status) !== 'held'; });

if (!runKey || !hasil.length) {
  return [{ json: { _kosong: true, run_key: runKey, hasil_bank: 'tidak_dikenal',
    pesan: 'Balasan bank tidak memuat run_key atau daftar results. Tidak ada yang ditulis.',
    di_berkas: diBerkas.length, tak_dibalas: [] } }];
}

const dibalas = {};
const keluar = hasil.map(function(r){
  const st = String(r.status||'').toLowerCase();
  const lunas = st === 'settled' || st === 'paid' || st === 'ok';
  const vendor = String(r.vendor||'').trim();
  const noFaktur = String(r.invoice_number||'').trim();
  const lineKey = runKey + '|' + vendor.toUpperCase() + '|' + noFaktur;
  const baris = perKunci[lineKey];
  const dikenal = !!baris && String(baris.status) !== 'held';
  if (dikenal) dibalas[lineKey] = true;
  return { json: {
    run_key: runKey, vendor: vendor, invoice_number: noFaktur, line_key: lineKey,
    bank_ref: String(r.bank_ref||''),
    hasil_bank: !dikenal ? 'tidak_dikenal' : (lunas ? 'settled' : 'rejected'),
    reject_reason: dikenal && !lunas ? String(r.reason || 'ditolak bank tanpa alasan tertulis') : '',
    settled_on: dikenal && lunas ? hariIni : '',
    amount: Number(r.amount||0),
    nilai_dikirim: baris ? Number(baris.amount||0) - Number(baris.discount_taken||0) : 0,
    alasan_tidak_dikenal: !baris
      ? 'Tidak ada baris ' + noFaktur + ' untuk ' + vendor + ' di ' + runKey + '.'
      : (String(baris.status) === 'held' ? 'Baris ini ditahan dan tidak pernah masuk berkas bank.' : ''),
    di_berkas: diBerkas.length
  }};
});

/* Yang ada di berkas tapi tidak disebut sama sekali oleh balasan ini dan
   statusnya masih to_pay: belum boleh dianggap lunas. */
const takDibalas = diBerkas
  .filter(function(r){ return String(r.status) === 'to_pay' && !dibalas[r.line_key]; })
  .map(function(r){ return { vendor: r.vendor, faktur: r.invoice_number,
    nilai: Number(r.amount||0) - Number(r.discount_taken||0) }; });
for (const k of keluar) k.json.tak_dibalas = takDibalas;
return keluar;

/* Rekonsiliasi balasan bank terhadap berkas yang dikirim:
   - lunas dan ditolak, dari balasan yang cocok dengan baris di berkas run itu
   - baris di berkas yang belum dibalas bank sama sekali
   - balasan untuk baris yang tidak pernah dikirim (tidak ditulis ke tabel)
   - lunas dengan jumlah yang berbeda dari yang dikirim
   "Baris diperbarui" dihitung dari baris yang benar-benar dikembalikan tabel. */
function rp(n){ return Number(n||0).toLocaleString('id-ID'); }
const balasan = $('Kumpulkan Hasil Bank').all().map(function(i){ return i.json; });
const pertama = balasan[0] || {};
const runKey = String(pertama.run_key||'');
const kosong = balasan.filter(function(r){ return r._kosong; });
const lunas = balasan.filter(function(r){ return r.hasil_bank === 'settled'; });
const tolak = balasan.filter(function(r){ return r.hasil_bank === 'rejected'; });
const asing = balasan.filter(function(r){ return r.hasil_bank === 'tidak_dikenal' && !r._kosong; });
const takDibalas = Array.isArray(pertama.tak_dibalas) ? pertama.tak_dibalas : [];
const beda = lunas.filter(function(r){ return Math.abs(Number(r.amount||0) - Number(r.nilai_dikirim||0)) > 1; });

let tertulis = [];
try { tertulis = $('Perbarui Baris Pembayaran').all().map(function(i){ return i.json; })
      .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { tertulis = []; }

function jum(a, f){ return a.reduce(function(s,r){ return s + Number(r[f||'amount']||0); }, 0); }
const dikenal = lunas.length + tolak.length;

return [{ json: {
  run_key: runKey,
  di_berkas: Number(pertama.di_berkas||0),
  dibalas: dikenal,
  lunas: lunas.length, nilai_lunas: jum(lunas),
  ditolak: tolak.length, nilai_ditolak: jum(tolak, 'nilai_dikirim'),
  tak_dibalas: takDibalas.length, nilai_tak_dibalas: jum(takDibalas, 'nilai'),
  tidak_dikenal: asing.length,
  baris_diperbarui: tertulis.length,
  baris_gagal_diperbarui: dikenal - tertulis.length,
  pesan_kosong: kosong.length ? String(kosong[0].pesan||'') : '',
  daftar_tolak: tolak.map(function(r){
    return { vendor:r.vendor, faktur:r.invoice_number, nilai:Number(r.nilai_dikirim||0), alasan:r.reject_reason };
  }),
  daftar_tak_dibalas: takDibalas,
  daftar_tidak_dikenal: asing.map(function(r){
    return { vendor:r.vendor, faktur:r.invoice_number, nilai:Number(r.amount||0), alasan:r.alasan_tidak_dikenal };
  }),
  daftar_beda: beda.map(function(r){
    return { vendor:r.vendor, faktur:r.invoice_number, dikirim:Number(r.nilai_dikirim||0), dibalas:Number(r.amount||0) };
  }),
  ringkas: lunas.length + ' lunas (' + rp(jum(lunas)) + ' IDR), ' + tolak.length + ' ditolak, '
    + takDibalas.length + ' belum dibalas, ' + asing.length + ' tidak dikenal'
}}];
